      function getAvatarInitials(primaryName, secondaryName) {
        const preferred = [primaryName, secondaryName].filter((value) => typeof value === "string" && value.trim()).map((value) => value.trim())[0] || "";
        if (!preferred) {
          return "U";
        }
        const tokens = preferred.split(/\s+/).filter(Boolean);
        if (tokens.length === 1) {
          return tokens[0].slice(0, 2).toUpperCase();
        }
        return (tokens[0][0] + tokens[1][0]).toUpperCase();
      }
